import json
from pathlib import Path

out=Path(__file__).parent
base='https://d8j0ntlcm91z4.cloudfront.net/user_3J1aVESwhbXLraSW8PtRFWWgpV2/hf_20260921_030316_'
tabs=[
    ('loading','Loading','f96e7714-f566-4283-a23d-3594f97441a9','Roster and collection setup share a compact two-column workspace. Saved coverage retains its status, cutoff, and evidence; mobile displays labeled rows.'),
    ('collection','Collection','88601a28-151d-4a8d-ad10-0d5aae46417b','Workers and activity appear alongside completed reports and run events. Coverage and freshness open on demand. Actual worker records retain their existing financial fields.'),
    ('graph','Graph','7cca69da-e085-4323-ba37-3da1bf76e904','Scope controls, analysis tabs, and a two-column chart workspace follow the reference hierarchy. Exact amounts, candidate views, and source actions remain intact.'),
    ('chart-studio','Chart Studio','397f0202-7b4a-497f-a14b-a2cb97e93833','One heading and a three-column builder at the reference size. Data and fields collapse on phones; Change data opens and focuses them. Canvas keeps its Inspector control.'),
    ('insights','Insights','d74bc9ba-f74b-43f0-8b23-ae340cfac3fe','Four scope controls lead into three analysis cards. Comparison and analysis selection are adjacent. Source, accounting basis, cutoffs, and record access remain available.'),
    ('cross-reference','Cross-reference','6ed6a439-384c-44c7-9398-4c368aeb8f0f','Compact scope and accounting context, aligned amounts, and separate evidence sections. Open disclosures and focused filing links survive same-run refreshes.'),
]
records=[dict(id=i,name=n,reference=base+r+'.png',capture=f'final-{i}-reference-size.png',width=1168,height=880,note=d) for i,n,r,d in tabs]
(out/'references.json').write_text(json.dumps(records,indent=2),encoding='utf-8')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mentat · Six-tab comparison</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#faf8f6;color:#342649;font:14px/1.5 Arial,sans-serif}header,main{padding:20px 28px}header{background:white;border-bottom:1px solid #e4d9d0}h1{font:700 28px Georgia,serif;margin:0 0 8px}p{margin:8px 0;max-width:95ch;color:#635a69}nav{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0 12px}button,select{font:inherit;border:1px solid #c6b9cf;border-radius:5px;padding:10px 14px;background:white;color:#342649;cursor:pointer}button[aria-pressed=true]{background:#342649;color:white}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #327a7a;outline-offset:3px}.controls{display:flex;align-items:center;gap:16px;flex-wrap:wrap}label{display:flex;gap:8px;align-items:center}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0;min-width:0}figcaption{font-weight:600;margin-bottom:10px}.frame{background:white;border:1px solid #e4d9d0;overflow:auto}img{display:block;width:100%;height:auto}.overlay{position:relative;max-width:1168px;margin:auto}.overlay img{width:100%}.overlay .actual{position:absolute;inset:0;width:100%;height:100%}.phone{max-width:390px;margin:auto}.links{display:flex;gap:18px;margin:16px 0;flex-wrap:wrap}a{color:#57447b;text-underline-offset:3px}[hidden]{display:none!important}@media(max-width:800px){.pair{grid-template-columns:1fr}header,main{padding:18px}}
</style>
<header><h1>Mentat · Six-tab comparison</h1><p>One reference and one local implementation for each tab, paired at 1168 × 880. Captures use isolated synthetic records. Actual evidence wording, longer source context, and working controls take precedence over generated mockup content; these are layout comparisons, not pixel-identical replicas.</p><nav aria-label="Choose a tab" id="tabs"></nav><div class="controls"><label>View<select id="mode"><option value="pair">Reference / implementation</option><option value="overlay">Overlay at matching dimensions</option><option value="full">Full local page</option><option value="mobile">Mobile · 390px</option></select></label><label id="blend-wrap" hidden>Implementation opacity<input id="blend" type="range" min="0" max="100" value="50"></label></div></header>
<main><p id="note"></p><div id="pair" class="pair"><figure><figcaption>Generated reference · 1168 × 880</figcaption><div class="frame"><img id="reference" alt=""></div></figure><figure><figcaption>Local implementation · 1168 × 880</figcaption><div class="frame"><img id="implementation" alt=""></div></figure></div><div id="overlay" class="overlay" hidden><img id="overlay-reference" alt=""><img id="overlay-actual" class="actual" alt="" style="opacity:.5"></div><div id="single" class="frame" hidden><img id="single-image" alt=""></div><div class="links"><a id="original-link" target="_blank" rel="noreferrer">Open original reference</a><a id="capture-link" target="_blank">Open local screenshot</a><a href="verification.md">Verification notes</a></div></main>
<script>
const tabs=RECORDS;
let active=tabs[0];const $=id=>document.getElementById(id);
function render(){const mode=$('mode').value;for(const button of $('tabs').children)button.setAttribute('aria-pressed',String(button.dataset.id===active.id));$('note').textContent=active.note;for(const id of ['reference','overlay-reference']){$(id).src=active.reference;$(id).alt=active.name+' generated reference';}for(const id of ['implementation','overlay-actual']){$(id).src=active.capture;$(id).alt=active.name+' local implementation';}$('pair').hidden=mode!=='pair';$('overlay').hidden=mode!=='overlay';$('blend-wrap').hidden=mode!=='overlay';$('single').hidden=!['full','mobile'].includes(mode);$('single').classList.toggle('phone',mode==='mobile');$('single-image').src='final-'+active.id+'-'+(mode==='mobile'?'390':'1168')+'.png';$('single-image').alt=active.name+' full local screenshot';$('original-link').href=active.reference;$('capture-link').href=active.capture;}
for(const tab of tabs){const button=document.createElement('button');button.type='button';button.textContent=tab.name;button.dataset.id=tab.id;button.onclick=()=>{active=tab;render();};$('tabs').append(button);}
$('mode').onchange=render;$('blend').oninput=()=>{$('overlay-actual').style.opacity=$('blend').value/100;};render();
</script></html>'''
(out/'comparison.html').write_text(html.replace('RECORDS',json.dumps(records)),encoding='utf-8')
